#include <stdio.h>
#include "jim.h"
static Jim_Obj *held;static const char *before;static int before_string;
static int make(Jim_Interp*i,int n,Jim_Obj*const*v){jim_wide mode;(void)n;Jim_GetWide(i,v[1],&mode);switch(mode){case 0:held=Jim_NewStringObj(i,"",0);break;case 1:held=Jim_NewStringObj(i,"0",1);break;case 2:held=Jim_NewStringObj(i,"{",1);break;case 3:held=Jim_NewIntObj(i,0);break;case 4:held=Jim_NewIntObj(i,2);break;case 5:held=Jim_NewDoubleObj(i,0.0);break;case 6:held=Jim_NewDoubleObj(i,2.0);break;case 7:held=Jim_NewListObj(i,NULL,0);break;case 8:{Jim_Obj*a=Jim_NewStringObj(i,"2",1);held=Jim_NewListObj(i,&a,1);break;}case 9:held=Jim_NewStringObj(i,"",0);break;case 10:held=Jim_NewStringObj(i,"2",1);break;case 14:held=Jim_NewIntObj(i,2);(void)Jim_String(held);break;case 15:held=Jim_NewDoubleObj(i,2.0);(void)Jim_String(held);break;case 16:held=Jim_NewStringObj(i,"true",4);{int b;(void)Jim_GetBoolean(i,held,&b);}break;default:if(mode==12){Jim_Obj*a[2]={Jim_NewStringObj(i,"2",1),Jim_NewStringObj(i,"3",1)};held=Jim_NewDictObj(i,a,2);}else held=Jim_NewDictObj(i,NULL,0);if(mode==13)(void)Jim_String(held);break;}Jim_IncrRefCount(held);before=held->typePtr?held->typePtr->name:"string";before_string=held->bytes!=NULL;Jim_SetResult(i,held);return JIM_OK;}
int main(void){int route,mode;for(route=0;route<2;route++)for(mode=0;mode<17;mode++){Jim_Interp*i=Jim_CreateInterp();char source[160];int code;Jim_RegisterCoreCommands(i);Jim_CreateCommand(i,"make",make,NULL,NULL);if(route)snprintf(source,sizeof(source),"proc f {} {set x [make %d]; llength $x}; f",mode);else snprintf(source,sizeof(source),"set x [make %d]; set cmd llength; $cmd $x",mode);code=Jim_Eval(i,source);printf("route=%d mode=%d before=%s beforestring=%d code=%d after=%s afterstring=%d result=",route,mode,before,before_string,code,held->typePtr?held->typePtr->name:"string",held->bytes!=NULL);{const unsigned char*s=(const unsigned char*)Jim_String(Jim_GetResult(i));for(;*s;s++)printf("%02x",*s);}puts("");Jim_DecrRefCount(i,held);Jim_FreeInterp(i);}return 0;}
